using Astrea.BattleActions;
using UnityEngine;

namespace Astrea;

[CreateAssetMenu(fileName = "PenitenceBurstEffect", menuName = "Data/Battle/Effects/Orion/PenitenceBurst Effect")]
public class PenitenceBurstEffect : Effect
{
	[Header("Penitence Burst")]
	[SerializeField]
	private OmenLogic omenLogic;

	[SerializeField]
	private CurrentCorruptedAnimals currentCorruptedAnimals;

	[Header("Description")]
	[SerializeField]
	private PurifyAction purifyAction;

	[SerializeField]
	private GainOtherEffectEffect gainOtherEffectEffect;

	public override string GetEffectDescription(int amount, GameObject effectOwner = null)
	{
		return gainOtherEffectEffect.GetKarmaActivatedBaseDescription(purifyAction.GetActionDescription((amount == EffectsValues.NO_VALUE) ? (-1) : amount)) + AppendedDescription();
	}

	public override int ActivateEffect(int effectAmount, GameObject effectOwner)
	{
		for (int i = 0; i < currentCorruptedAnimals.activeCorruptedAnimals.Count; i++)
		{
			SpawnSecondVFX(GetVFXOwnerPosition(currentCorruptedAnimals.activeCorruptedAnimals[i]), 3f);
		}
		PlayEffectActivationSFX();
		omenLogic.ActivateOmen(null, effectAmount, null, null);
		SpawnVFXOnPlayerPosition(3f);
		return effectAmount;
	}
}
